  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'সেটিংস খুলুন, নিরাপত্তাতে যান, তারপর পাসওয়ার্ড বা দ্বি-ফ্যাক্টর ডায়ালগ ব্যবহার করুন। কনফিগার করা হলে দ্বি-ফ্যাক্টর ডেলিভারি ইমেল বা ফোন সমর্থন করে।',
