  'Playback' => 'প্লেব্যাক',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'প্রমাণীকৃত প্ল্যাটফর্ম বৈশিষ্ট্যগুলির সাথে লিঙ্ক করা হলে প্লেব্যাকের অগ্রগতি, পরে দেখার অবস্থা, পছন্দ, মন্তব্য, সদস্যতা, বিজ্ঞপ্তি এবং অ্যাডমিন বিশ্লেষণগুলি ডাটাবেসে সংরক্ষণ করা হয়।',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'প্লেব্যাক, মন্তব্য, লাইক, পরে দেখুন, সদস্যতা, বিজ্ঞপ্তি, বার্তা, প্লেলিস্ট এবং ভাষা সেটিংস প্রধান নেভিগেশন এবং অ্যাকাউন্ট মেনুর মাধ্যমে উপলব্ধ।',
  'PlayHub' => 'প্লেহাব',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'প্লেহাব হল একটি অ্যাকাউন্ট থেকে ক্রিয়েটর সামগ্রী আপলোড, দেখা, সময়সূচী, পরিচালনা এবং নিয়ন্ত্রণ করার জন্য একটি ভিডিও প্ল্যাটফর্ম৷',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub হল এই স্থাপনার উপর চলমান ভিডিও প্ল্যাটফর্ম, যা নির্মাতা, দর্শক, সম্প্রদায় এবং প্ল্যাটফর্ম অপারেটরদের জন্য তৈরি করা হয়েছে।',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'প্লেহাব একটি প্ল্যাটফর্ম থেকে নির্মাতার চ্যানেল, ভিডিও আপলোড, নির্ধারিত প্রকাশনা, সদস্যতা, মন্তব্য, প্লেলিস্ট, পরে দেখুন, লাইভ সামগ্রী পৃষ্ঠা এবং প্রশাসনিক সরঞ্জাম সরবরাহ করে।',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub লগইন সেশন, API প্রমাণীকরণ, CSRF/নিরাপত্তা আচরণ, ভাষা নির্বাচন, থিম নির্বাচন, অ্যাকাউন্ট মেনু অবস্থা এবং অ্যাপ্লিকেশন কাজ করার জন্য প্রয়োজনীয় অন্যান্য বৈশিষ্ট্যগুলির জন্য প্রয়োজনীয় কুকিজ এবং ব্রাউজার স্টোরেজ ব্যবহার করে।',
  'playhub_language, theme' => 'playhub_language, থিম',
