  'The configured' => 'কনফিগার করা',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'বিকাশকারী পৃষ্ঠাটি লাইভ লারাভেল ব্যাকএন্ডের সাথে সংযুক্ত: রুট ইনভেন্টরি, ডাটাবেস গণনা, আপলোড সীমা এবং প্ল্যাটফর্ম মেটাডেটা /api/developers থেকে লোড করা হয়।',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'ফ্রন্টএন্ড পছন্দগুলি যেমন নির্বাচিত ভাষা, থিম, প্লেব্যাক সারি, ঘড়ির অগ্রগতি এবং ইন্টারফেস স্থিতি সংরক্ষণ করে যাতে অভিজ্ঞতাটি পৃষ্ঠা নেভিগেশন এবং পুনরায় লোড জুড়ে সামঞ্জস্যপূর্ণ থাকে।',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'প্রসেসিং জব রেন্ডিশনগুলিকে এনকোড করে, প্রয়োজনে থাম্বনেইল তৈরি করে, ক্যাপশন সঞ্চয় করে এবং প্রসেসিং সম্পূর্ণ হলে ভিডিওগুলিকে প্রস্তুত চিহ্নিত করে৷ ভবিষ্যত নির্ধারিত ভিডিওগুলি যতক্ষণ না সময়সূচী প্রকাশ করে ততক্ষণ পর্যন্ত ব্যক্তিগত থাকে৷',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'আপলোড সিস্টেমটি ডাটাবেস-সমর্থিত, API থেকে বিভাগ এবং ভাষাগুলিকে সমর্থন করে, আপলোড করা ভিডিওগুলি প্রক্রিয়া করে, থাম্বনেল এবং ক্যাপশনগুলি সঞ্চয় করে এবং প্রকাশের সময় পর্যন্ত নির্ধারিত বিষয়বস্তু ব্যক্তিগত রাখে৷',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'এই পৃষ্ঠাটি ব্যাখ্যা করে কিভাবে PlayHub সেশন, নিরাপত্তা, পছন্দ, প্লেব্যাক এবং প্রমাণীকৃত বৈশিষ্ট্যের জন্য কুকিজ এবং ব্রাউজার স্টোরেজ ব্যবহার করে।',
  'Ticket source' => 'টিকিটের উৎস',
  'Top content categories' => 'শীর্ষ বিষয়বস্তু বিভাগ',
  'Topic' => 'বিষয়',
  'Transaction / invoice' => 'লেনদেন / চালান',
  'Transaction / invoice ID' => 'লেনদেন / চালান আইডি',
  'Unable to send message.' => 'বার্তা পাঠাতে অক্ষম।',
  'Unable to submit refund request.' => 'ফেরত অনুরোধ জমা দিতে অক্ষম.',
  'Understanding admin support tickets' => 'অ্যাডমিন সমর্থন টিকিট বোঝা',
  'Upload and processing help' => 'আপলোড এবং প্রক্রিয়াকরণ সাহায্য',
  'Upload chunks' => 'খণ্ড আপলোড',
  'Upload issues' => 'আপলোড সমস্যা',
  'Upload languages' => 'ভাষা আপলোড করুন',
  'Upload limit' => 'আপলোড সীমা',
  'Upload options' => 'আপলোড অপশন',
  'Upload or processing' => 'আপলোড বা প্রক্রিয়াকরণ',
  'Upload page' => 'পৃষ্ঠা আপলোড করুন',
  'Upload pipeline' => 'পাইপলাইন আপলোড করুন',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'লাইভ PlayHub ডেটা দিয়ে আপলোড করুন, দেখুন, সদস্যতা নিন, মডারেট করুন এবং বিল্ড করুন।',
  'Uploaded videos' => 'আপলোড করা ভিডিও',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'আপলোড করা ভিডিওগুলি প্লেযোগ্য উপস্থাপনায় এনকোড করা হয়৷ প্রক্রিয়াকরণের সময় ফাইলের আকার, সময়কাল, সার্ভার লোড এবং সারির অবস্থার উপর নির্ভর করে। আপলোড পৃষ্ঠা এবং নির্মাতা স্টুডিও ভিডিও রেকর্ড থেকে বাস্তব প্রক্রিয়াকরণের অবস্থা দেখায়।',
  'Uploads, scheduling, and processing are available.' => 'আপলোড, সময়সূচী, এবং প্রক্রিয়াকরণ উপলব্ধ.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'নির্মাতার কর্মপ্রবাহের জন্য /api/ভিডিও, চ্যানেল এন্ডপয়েন্ট এবং প্রমাণীকৃত রুট ব্যবহার করুন।',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ভিডিও এবং মন্তব্যের জন্য বিল্ট-ইন রিপোর্ট অ্যাকশন ব্যবহার করুন যাতে অ্যাডমিনরা সঠিক কন্টেন্ট রেফারেন্স পান। অ্যাডমিন ড্যাশবোর্ড পৃষ্ঠাগুলি ব্যবহারকারী, বিষয়বস্তু, প্রতিবেদন, নগদীকরণ, বিশ্লেষণ, সমর্থন, ভূমিকা এবং সিস্টেম সেটিংসের জন্য লাইভ ডাটাবেস ডেটা ব্যবহার করে।',
  'Use Contact Us' => 'আমাদের সাথে যোগাযোগ করুন ব্যবহার করুন',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'সাধারণ API অনুরোধের জন্য JSON এবং ফাইল আপলোডের জন্য FormData ব্যবহার করুন। বৈধতা বাইপাস করবেন না: বিভাগ এবং ভাষাগুলি ডাটাবেস আইডি, দৃশ্যমানতা সর্বজনীন, তালিকাভুক্ত বা ব্যক্তিগত পর্যন্ত সীমাবদ্ধ এবং ক্যাপশনগুলি SRT, VTT, বা TXT ফাইলগুলিকে গ্রহণ করে৷',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'আপনার প্রোফাইল, নিরাপত্তা, পাসওয়ার্ড, দ্বি-ফ্যাক্টর ডেলিভারি, ডিভাইস, পছন্দ এবং বিজ্ঞপ্তি বিকল্প আপডেট করতে সেটিংস ব্যবহার করুন। আপনি যদি আপনার অ্যাকাউন্ট অ্যাক্সেস করতে না পারেন, লগইন ফ্লো ব্যবহার করুন এবং সাইট প্রশাসককে অ্যাকাউন্ট ইমেল প্রদান করুন।',
  'Use the contact form' => 'যোগাযোগ ফর্ম ব্যবহার করুন',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ভিডিও, মন্তব্য এবং সম্প্রদায়ের পোস্টগুলিতে প্রতিবেদনের ক্রিয়াগুলি ব্যবহার করুন যাতে প্রশাসকরা সঠিক বিষয়বস্তুর রেফারেন্স পান৷',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'যখন বিষয়বস্তু প্ল্যাটফর্মের নিয়ম লঙ্ঘন করতে পারে তখন ভিডিও, মন্তব্য এবং সম্প্রদায়ের পোস্টে রিপোর্ট অ্যাকশন ব্যবহার করুন। এই প্রতিবেদনগুলি প্রকৃত বিষয়বস্তু রেকর্ডের সাথে আবদ্ধ এবং একটি সাধারণ বার্তার চেয়ে ভাল কারণ প্রশাসকরা সঠিক আইটেমটি পর্যালোচনা করতে পারেন৷',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'অ্যাকাউন্ট সহায়তা, বিষয়বস্তু প্রতিবেদন, প্রযুক্তিগত সমস্যা এবং প্রশাসকের অনুরোধের জন্য সঠিক PlayHub চ্যানেল ব্যবহার করুন।',
  'Video categories' => 'ভিডিও বিভাগ',
  'Video for everyone. Built for creators and viewers.' => 'ভিডিও সবার জন্য। বাস্তব প্ল্যাটফর্ম ডেটা থেকে নির্মিত.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ভিডিও আপলোড, সময়সূচী, থাম্বনেল, এবং প্রক্রিয়াকরণ সমস্যা.',
  'Videos, thumbnails, captions, processing.' => 'ভিডিও, থাম্বনেল, ক্যাপশন, প্রক্রিয়াকরণ।',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'দর্শকরা বিভাগগুলি ব্রাউজ করতে, ভিডিওগুলি অনুসন্ধান করতে, সামগ্রী দেখতে, চ্যানেলগুলিতে সদস্যতা নিতে, পরে দেখার জন্য ভিডিওগুলি সংরক্ষণ করতে, মন্তব্য করতে, বিজ্ঞপ্তিগুলি গ্রহণ করতে এবং ভাষা এবং অ্যাক্সেসযোগ্যতার পছন্দগুলি পরিচালনা করতে পারে৷',
  'Viewing and community help' => 'দেখা এবং সম্প্রদায় সাহায্য',
  'Waiting for backend endpoint inventory.' => 'ব্যাকএন্ড এন্ডপয়েন্ট ইনভেন্টরির জন্য অপেক্ষা করা হচ্ছে।',
  'We’re here to help.' => 'আমরা সাহায্য করতে এখানে আছি।',
  'What is PlayHub?' => 'PlayHub কি?',
  'What PlayHub does' => 'PlayHub কি করে',
  'Where do contact messages go?' => 'যোগাযোগের বার্তা কোথায় যায়?',
  'Why is my video still processing?' => 'কেন আমার ভিডিও এখনও প্রক্রিয়া করা হচ্ছে?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'হ্যাঁ। আপলোড পৃষ্ঠায় নেটিভ শিডিউল তারিখ এবং সময় ক্ষেত্র ব্যবহার করুন। ব্যাকএন্ড নির্ধারিত_এটি সঞ্চয় করে, ভিডিওটি প্রক্রিয়া করে, তারিখটি ভবিষ্যতে থাকাকালীন এটিকে ব্যক্তিগত রাখে এবং যখন লারাভেল শিডিউলার নির্ধারিত সময়ের পরে চলে তখন এটি প্রকাশ করে।',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'হ্যাঁ। আপলোডে নেটিভ শিডিউল ফিল্ড ব্যবহার করুন। ব্যাকএন্ড নির্ধারিত_এ সঞ্চয় করে এবং সময়সূচীর সময় পৌঁছে গেলে প্রক্রিয়াকরণের পর ভিডিও প্রকাশ করে।',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'আপনি একটি অতিথি হিসাবে ব্রাউজ করছেন. অ্যাকাউন্ট-নির্দিষ্ট টুল অ্যাক্সেস করতে সাইন ইন করুন।',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'আপনি আপনার অ্যাকাউন্টের শংসাপত্র, প্রোফাইল কার্যকলাপ, আপলোড করা সামগ্রী, মন্তব্য, বার্তা এবং আপনার অ্যাকাউন্ট থেকে সঞ্চালিত যেকোনো নির্মাতা বা প্রশাসকের ক্রিয়াকলাপের জন্য দায়ী৷ শক্তিশালী পাসওয়ার্ড ব্যবহার করুন এবং দ্বি-ফ্যাক্টর বিতরণ পদ্ধতি বর্তমান রাখুন।',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'আপনি আপনার ব্রাউজার সেটিংসে ব্রাউজার কুকিজ এবং স্থানীয় স্টোরেজ সাফ করতে পারেন। অত্যাবশ্যকীয় সঞ্চয়স্থান সাফ করা আপনাকে সাইন আউট করতে পারে, ভাষা/থিম পছন্দগুলি পুনরায় সেট করতে পারে, স্থানীয় প্লেব্যাক অবস্থা সরাতে পারে এবং আপনাকে আবার লগ ইন করতে হবে৷',
  'You receive a response by email.' => 'আপনি ইমেল দ্বারা একটি প্রতিক্রিয়া পাবেন.',
  'You’re in control' => 'আপনি নিয়ন্ত্রণে আছেন',
  'Your choices' => 'আপনার পছন্দ',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'আপনার বার্তা সরাসরি ওয়েবসাইট ব্যাকএন্ডে সংরক্ষিত হয় এবং সহায়তার অধীনে অ্যাডমিন ড্যাশবোর্ডে প্রদর্শিত হয়।',
  'Your support' => 'আপনার সমর্থন',
  'Watch video' => 'ভিডিও দেখুন',
  'Copy link' => 'লিঙ্ক কপি করুন',
