  'Video: {seconds}s · {width}×{height}. Shorts must be 60 seconds or less and vertical.' => 'ভিডিও: {seconds} সেকেন্ড · {width}×{height}। Shorts ভিডিও খাড়া হতে হবে এবং সর্বোচ্চ ৬০ সেকেন্ডের হতে পারবে।',
  'Shorts must be 180 seconds or less.' => 'Shorts সর্বোচ্চ ৬০ সেকেন্ডের হতে পারে।',
  'Shorts must be square or vertical.' => 'Shorts ভিডিও খাড়া হতে হবে।',
  'Shorts must be 180 seconds or less and square or vertical.' => 'Shorts ভিডিও খাড়া হতে হবে এবং সর্বোচ্চ ৬০ সেকেন্ডের হতে পারবে।',
  'This video will be published as a Short because it is at most 180 seconds and square or vertical.' => 'এই ভিডিওটি খাড়া এবং সর্বোচ্চ ৬০ সেকেন্ডের, তাই এটি Short হিসেবে প্রকাশিত হবে।',
  'No shorts uploaded yet. Shorts appear here after a square or vertical video of at most 180 seconds is imported.' => 'এখনো কোনো Shorts নেই। ইমপোর্ট করা সর্বোচ্চ ৬০ সেকেন্ডের খাড়া ভিডিও এখানে দেখা যাবে।',
  'Shorts must be square or vertical videos of at most 180 seconds.' => 'Shorts ভিডিও খাড়া হতে হবে এবং সর্বোচ্চ ৬০ সেকেন্ডের হতে পারবে।',
  '· Shorts require 60s max and vertical video' => '· Shorts ভিডিও খাড়া হতে হবে এবং সর্বোচ্চ ৬০ সেকেন্ডের হতে পারবে',
  '· Shorts require 180s max and square or vertical video' => '· Shorts ভিডিও খাড়া হতে হবে এবং সর্বোচ্চ ৬০ সেকেন্ডের হতে পারবে',
  'Your video was imported.' => 'তোমার ভিডিও ইমপোর্ট হয়েছে।',
