  'Automatic detection' => 'স্বয়ংক্রিয় শনাক্তকরণ',
  'Provider detected automatically' => 'প্ল্যাটফর্ম স্বয়ংক্রিয়ভাবে শনাক্ত হয়েছে',
  'Selected provider' => 'বেছে নেওয়া প্ল্যাটফর্ম',
