  'No available subtitle tracks found.' => 'কোনো উপলব্ধ সাবটাইটেল ট্র্যাক পাওয়া যায়নি।',
  'Review or disable them before publishing.' => 'প্রকাশ করার আগে অধ্যায়গুলো যাচাই করো। চাইলে সেগুলো বন্ধও করতে পারো।',
