  'Imports video details, available subtitles and chapters from YouTube.' => 'YouTube থেকে ভিডিওর তথ্য, উপলব্ধ সাবটাইটেল ও অধ্যায় ইমপোর্ট করে।',
  'Automatic (original language)' => 'স্বয়ংক্রিয় (মূল ভাষা)',
