  'Chapter timestamps must be in order and at least {seconds} seconds apart.' => 'অধ্যায়ের সময়গুলো ক্রমানুসারে থাকতে হবে এবং অন্তত {seconds} সেকেন্ড ব্যবধান থাকতে হবে।',
  'Chapter {number} starts after the video ends.' => 'অধ্যায় {number} ভিডিও শেষ হওয়ার আগে শুরু হতে হবে।',
  'Add a name for chapter {number} or turn off Upload with chapters.' => 'অধ্যায় {number}-এর নাম দাও বা অধ্যায় যুক্ত করো বিকল্পটি বন্ধ করো।',
  'The name for chapter {number} must be 160 characters or fewer.' => 'অধ্যায় {number}-এর নাম 160 অক্ষরের মধ্যে হতে হবে।',
